(function(){
  'use strict';
  const X=window.OrchardExpression,G=window.OrchardGuidance;
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ref=(page,section)=>[['enquiry',page,section]];
  G.registerDefinitions({
    overlap:{title:'Overlap count',aliases:['overlap count'],plain:'How many required components are included in a question.',math:'s=|K∩q|, with known cardinality c=|K|. Audited K is available during calibration and validation. Fresh runtime diagnosis never receives the actual K.',refs:ref(1,'§2, response semantics')},
    expressiongrammar:{title:'Fixed expression grammar',aliases:['expression grammar','26-program grammar'],plain:'Stage four’s supplied menu of possible response rules. Stage five can acquire a qualified, bounded extension of its construction procedure.',math:'G consists of ≥, =, ≤ comparisons of s with 0,1,2,3,4,c,c−1 (21 programs), plus every residue modulo 2 and 3 (5 programs). Stage four keeps this syntax, interpreter and selector fixed. Stage five retains G₀ and adds 21 supplied Boolean equality pairs: 47 syntactic programs under a fixed meta-grammar. Selecting one program and expanding construction reachability are separate operations.',refs:ref(3,'§4, supplied grammar')},
    calibration:{title:'Calibration evidence',aliases:['calibration evidence','calibration observations'],plain:'Trusted exact-set feedback and measured answers used to choose an expression. These are learning examples, separate from later tests.',math:'Four audited failures at n∈{4,5}, c∈{2,3}. Collect every proper nonempty q: 2·14+2·30=88 (n,c,K,q,y) observations. Exact K is supplied by the audit; the learner receives no response-mechanism name.',refs:ref(3,'§4, audited failures and 88 observations')},
    survivors:{title:'Candidate survivors',aliases:['candidate survivors','surviving candidates','candidate consistency'],plain:'Programs that disagree with none of the calibration answers. Only one survivor may advance to validation.',math:'V(D)={g∈G:∀(n,c,K,q,y)∈D, g(K,q,c)=y}. |V|=0: no candidate; |V|>1: ambiguity; |V|=1: selected relative to G and D, not universally proven.',refs:ref(3,'§4, V(D)'),},
    semanticvalidation:{title:'Semantic validation',aliases:['semantic validation','validation measurements'],plain:'Separate measured examples used to check the selected rule before installing it. These examples have been inspected during development and are not held-out runtime tests.',math:'n=6, c∈{2,3,4}: (15+20+15)·62=3,100 observations. Require complete distinct (c,K,q) coverage and zero mismatches. This finite check does not authenticate the feedback source or establish all-dimensional semantics.',refs:ref(3,'§4.1, semantic validation')},
    expressioncertificate:{title:'Expression certificate',aliases:['expression certificate','certificate replay'],plain:'A retained record binding the expression, supplied evidence and finite checked scope. Restoring an expression rechecks that record.',math:'The local artifact stores g, D, V, G and an exact serialized binding. Replay recomputes selection and validation and compares the certificate. Honest-host structural checking, not a cryptographic signature, sandbox or source authentication.',refs:ref(3,'§4.1, binding and retention')},
    holdout:{title:'Held-out runtime census',aliases:['held-out runtime','held-out census','fresh dimension'],plain:'Fresh situations not used to select or validate the expression. Their true required sets are reserved for the response simulator and separate scoring.',math:'This toy freezes g after n=4/5 calibration and n=6 validation, then enumerates all 35 K at n=7,c=3 under AND/XOR/OR: 105 episodes per arm. Two further predicates form a separate 70-episode stress family. No runtime outcome revises g.',refs:ref(4,'§5, frozen census and controls')},
    supportexpansion:{title:'Library enlargement can reopen doubt',aliases:['library enlargement','reopened ambiguity'],plain:'Adding a possible explanation can reveal alternatives that the smaller library missed. More knowledge of possible models can initially mean less certainty about the action.',math:'For fixed O and L₀⊆L₁, H(L₀,O)⊆H(L₁,O) and A(L₀,O)⊆A(L₁,O). An old singleton action set may become larger. Later adaptive query histories need not have identical costs or completion rates.',refs:ref(5,'§8, Proposition 2')},
    residualpredicates:{title:'Uninstalled stress predicates',aliases:['at-least-two predicate','exactly-one predicate'],plain:'Two possible response rules that remain absent from the enlarged working library, even though the supplied grammar can express them.',math:'GE2: y=1 iff s≥2. EQ1: y=1 iff s=1. This stage installs only its uniquely acquired s≥1 candidate. Stress results are scored separately; no second acquisition round occurs.',refs:ref(5,'§7, remaining coverage failure')}
  });
  function run(input){
    if(!input||input.protocol!=='orchard-lab/1')throw new Error('Unsupported laboratory protocol.');
    const p=input.previous;if(p&&(p.experiment!=='constructive-enquiry'||p.protocol!=='orchard-lab/1'||!p.passed||p.authorityExpanded!==false))throw new Error('Stage four requires the checked enquiry milestone.');
    if(p)X.verifyGap(p.auditedGap);
    const evidence=X.makeEvidence(p?p.auditedGap:null),a=X.acquire(evidence),c=X.comparison(a.artifact),main=c[0].main,removed=c[1].main;
    const held=X.run({permission:false},X.library(a.artifact));
    return {protocol:'orchard-lab/1',experiment:'acquired-expression',passed:a.status==='qualified'&&main.correct===105&&main.incorrect===0&&removed.incorrect===34&&held.reason==='receiving-permission',summary:'Selected s≥1 from 26 programs using 88 audited observations; validated 3,100 measurements. Fresh n=7/c=3: retained/restored expression 105/105 correct; removal 71 correct and 34 wrong. Separate residual stress: 68/70 wrong with the retained expression. Permissions remain separate.',previousConsumed:!!p,transfer:p?'audited-calibration-gap':'none',evidenceTransfer:p?'initiating-audit-only':'none',runtimeEvidenceTransfer:'none',authorityExpanded:false,grammarExpanded:false,selectorChanged:false,expressionArtifact:a.artifact,comparison:c.map(({outcomes,...row})=>row)};
  }
  function mount({container}){
    const abort=new AbortController(),options={budget:48,price:'unit',permission:false,queryPermission:true,refreshPermission:true,watch:true,stale:false,mode:'OR',K:11};
    let evidence=null,selection=null,qualification=null,artifact=null,result=null,comparison=null,stage=0,knownFailure=false,runtimeError=null,auditMessage=null;
    const stages=[['Notice','A wrong answer can expose a missing model','The old AND/XOR library proposes {0,1,2} for a supplied OR world whose required set is {0,1,3}. An independently trusted exact-set audit can reveal the contradiction. The audit does not supply a mechanism name to the learner or grant use.'],['Audit','Collect trusted calibration evidence','Four small audited failures supply the true dependency sets. The response channel supplies all proper nonempty query answers. Keep this learning evidence separate from six-component validation and fresh seven-component runtime tests.'],['Select','Search the supplied expression grammar','Compare every candidate with every calibration observation. Missing trust, no survivor or multiple candidate survivors causes a hold. The grammar already contains the missing expression; this is selection within a fixed language.'],['Validate','Try the candidate before installation','A unique candidate advances to semantic validation. Check 3,100 separate measurements with full distinct coverage. Zero mismatches qualifies only this finite evidence scope; it cannot manufacture universal coverage.'],['Install','Retain a checked expression','Certificate replay rechecks the expression and evidence before installation. The library becomes AND/XOR plus the acquired rule. The selector, interpreter and enquiry compiler stay fixed. Receiving permission remains off unless separately supplied.'],['Retest','Let the enlarged model guide new questions','Test fresh dimension n=7,c=3. Library enlargement can reopen an old unanimous answer, requiring additional enquiry. Compare removal, restoration and conventional expanded diagnosis, then inspect the remaining outside-library failures.']];
    container.innerHTML=`<section class="intro"><div><div class="chapter">Encounter 04 · Acquired expression</div><h1>Learn What Was Missing</h1><p>Use an audited failure to acquire a missing response rule. Watch it change which questions the system knows it needs to ask—and test where the repair still stops short.</p></div><div class="intro-note">A fixed language.<br>A new installed expression.<br>Fresh evidence and permission.</div></section>
    <section class="panel guided-experience" aria-label="Expression guided experience"><div class="guide-topline"><span id="expression-guide-count"></span><span class="helper">Dotted terms open English, mathematics and source pages.</span></div><div class="guide-steps" id="expression-steps"></div><h2 id="expression-guide-title"></h2><p id="expression-guide-description"></p><div class="execution-controls"><button class="quiet" id="expression-back">Previous stage</button><button class="primary" id="expression-next">Next stage</button><button class="secondary" id="expression-glossary">Browse all definitions</button></div></section>
    <div class="workspace expression-workspace"><aside class="controls enquiry-controls"><h2>Acquire one response rule</h2><p class="helper">Overlap count: s=|K∩q|.</p><div class="expression-pipeline"><button class="secondary wide-button" id="expression-audits">1 · Collect audited failures</button><button class="secondary wide-button" id="expression-select">2 · Select a candidate</button><button class="secondary wide-button" id="expression-validate">3 · Validate the candidate</button><button class="primary wide-button" id="expression-install">4 · Install checked expression</button></div><p class="helper" id="expression-learning-status" aria-live="polite"></p><details class="assumptions"><summary>Acquisition boundary probes</summary><label class="checkbox-line"><input id="expression-trusted" type="checkbox" checked>Trust the supplied audit source</label><label class="field" for="expression-data">Calibration evidence<select id="expression-data"><option value="full">All four cases and 88 answers</option><option value="sparse">One answer only · ambiguity probe</option><option value="conflict">Contradictory duplicate answer</option></select></label><label class="checkbox-line"><input id="expression-grammar" type="checkbox">Remove s≥1 from the available grammar</label><label class="checkbox-line"><input id="expression-bad-validation" type="checkbox">Corrupt one validation answer</label><label class="checkbox-line"><input id="expression-stale-feedback" type="checkbox">Change the audited source version</label><p class="helper">Changing these probes clears the acquired expression. They affect supplied development evidence; no fresh runtime scoring enters selection.</p></details></aside>
    <div><div class="metrics"><div class="metric"><div class="metric-name">Candidate survivors</div><div class="metric-value" id="expression-survivors">—</div><div class="metric-detail">Required: exactly 1</div></div><div class="metric"><div class="metric-name">Calibration observations</div><div class="metric-value" id="expression-calibration">0</div><div class="metric-detail">Full scope: 88 measurements</div></div><div class="metric"><div class="metric-name">Validation mismatches</div><div class="metric-value" id="expression-mismatches">—</div><div class="metric-detail">Acceptance ceiling: 0 / 3,100</div></div></div>
    <section class="context-map"><h2>What has actually changed?</h2><div class="expression-library" id="expression-library"></div><p class="helper" id="expression-certificate"></p></section><div class="state-explanation" id="expression-explanation" aria-live="polite"></div>
    <section class="panel evidence-panel"><h2>Which programs survive the evidence?</h2><p>The full expression grammar has 26 programs. Every available program is tested; zero mismatches means candidate consistency. Validation and installation replay are still required.</p><details><summary>Inspect the candidate mismatch ledger</summary><div id="expression-ledger"></div></details></section></div></div>
    <section class="panel evidence-panel"><h2>The audit-to-learning boundary</h2><p id="expression-data-description">No calibration feedback collected yet. The default runtime below uses the smaller old library.</p><div class="table-wrap" id="expression-case-table"></div><details><summary>Inspect supplied measurement scopes</summary><p>Calibration: n=4/5, c=2/3. Validation: n=6, c=2/3/4. Held-out runtime: n=7, c=3. Exact K is supplied only during development; runtime sees query responses and operational metadata. These are noiseless authored fixtures with known cardinality and trusted exact-set measurements.</p><p>The earlier stage-three census is not silently repurposed as training data. In the shared sequence, a typed audited gap initiates one calibration case. Other learning measurements are freshly supplied. No mechanism name is passed to the candidate selector.</p></details></section>
    <section class="panel evidence-panel"><h2>Try a fresh diagnostic episode</h2><p>Choose whether the acquired expression is present. The true set is a simulator setting; diagnosis never reads it.</p><div class="expression-runtime-controls"><label class="field">Library intervention<select id="expression-arm"><option value="inherited">Retain the acquired expression</option><option value="removed">Remove only the expression</option><option value="restored">Restore exact expression and certificate</option><option value="active">Conventional expanded diagnosis</option></select></label><label class="field">Runtime tick budget<select id="expression-budget"><option value="6">6 ticks</option><option value="12">12 ticks</option><option value="18">18 ticks</option><option value="24">24 ticks</option><option value="48" selected>48 ticks</option><option value="64">64 ticks</option></select></label><label class="field">Query price<select id="expression-price"><option value="unit">1 unit per query</option><option value="width">1 unit per selected component</option></select></label></div><label class="checkbox-line"><input id="expression-permission" type="checkbox">Current receiving permission · starts off</label><div class="execution-controls"><button class="primary" id="expression-run">Run fresh episode</button><button class="secondary" id="expression-compare">Run frozen held-out census</button><button class="quiet" id="expression-reset">Reset this experiment</button></div><details class="assumptions"><summary>Runtime environment and release probes</summary><div class="expression-runtime-controls"><label class="field">Simulator response mechanism<select id="expression-mode"><option>OR</option><option>AND</option><option>XOR</option><option value="GE2">At least two · not installed</option><option value="EQ1">Exactly one · not installed</option></select></label><label class="field">Actual required set · simulator only<select id="expression-K">${X.sets(7,3).map(K=>`<option value="${K}" ${K===11?'selected':''}>${X.setName(K)}</option>`).join('')}</select></label></div><label class="checkbox-line"><input id="expression-query" type="checkbox" checked>Query permission</label><label class="checkbox-line"><input id="expression-refresh" type="checkbox" checked>Dependency-refresh permission</label><label class="checkbox-line"><input id="expression-watch" type="checkbox" checked>Service continuing watches</label><label class="checkbox-line"><input id="expression-stale" type="checkbox">Change source version after qualification</label><label class="checkbox-line"><input id="expression-bad-certificate" type="checkbox">Tamper with retained expression certificate</label></details><div class="state-explanation" id="expression-runtime-result" aria-live="polite"></div></section>
    <div class="lower-grid"><section class="panel"><h2>Adding a model can reopen doubt</h2><p>Same observations at the end of the initial AND tree; compare the old and enlarged libraries before any additional questions.</p><div id="expression-reopen"></div></section><section class="panel"><h2>Then new questions narrow the gap</h2><p>Blue: current-library route. Orange: old-library route. Each follows its own query history. In the inherited routes, initial AND-tree observations match; active diagnosis starts from its own root.</p><div id="expression-progress"></div></section></div>
    <section class="panel evidence-panel"><h2>Receiving checks and continuing duties</h2><p id="expression-watch-summary"></p><div class="tick-grid" id="expression-ticks"></div><p class="helper">Q · query; R · refresh; C · receipt qualification; A · admission check; W · watch; ! · missed watch; · · idle. Development runs outside this simulated runtime window.</p><details><summary>Inspect the fresh query trace and work counters</summary><div id="expression-runtime-trace"></div></details><div class="execution-controls"><button class="secondary" id="expression-runtime-audit">Audit this fresh episode</button></div><p id="expression-runtime-audit-result"></p></section>
    <section class="panel evidence-panel"><h2>Frozen comparison on a fresh dimension</h2><p>105 main episodes per arm: every three-component required set at n=7 under AND/XOR/OR. All arms receive fresh supplied query, refresh and receiving permissions with serviced watches. Your live controls keep their current permissions. Conventional diagnosis starts with the same expanded library; no acquisition advantage is credited to it.</p><p id="expression-comparison-description">Install a checked expression, then run the census. No census outcome is used to revise it.</p><div class="lower-grid"><div><h3>Represented family · 105 episodes</h3><div id="expression-main-census"></div></div><div><h3>Residual stress · 70 separate episodes</h3><p>The at-least-two predicate and exactly-one predicate are expressible but uninstalled. Stress always uses 64 ticks at the selected query price; no second learning round is run.</p><div id="expression-stress-census"></div></div></div><div class="census-legend"><span class="correct-key">Correct admission</span><span class="incorrect-key">Incorrect admission</span><span class="hold-key">Withheld</span></div></section>
    <details class="panel evidence-panel"><summary>What this adds to the MeRSIA pathway</summary><p>The acquired expression changes the hypothesis family from which later enquiry plans are constructed. Removal and exact restoration test that bounded causal contribution. This is model-library extension: the expression grammar, selector, interpreter and enquiry compiler remain supplied and fixed.</p><p>The paper’s calibration and validation scope is used here, while the held-out census is a smaller educational reconstruction. Its larger published results are not reproduced by this toy. Selected operation counters omit support enumeration, binding, host work and some checking. No total-compute, elapsed-time, universal safety or rate-dominance claim is established.</p><p>A later meta-extensibility experiment would need to change and qualify the construction machinery itself, then test whether that change improves subsequent acquisition. A working new tab does not establish that result.</p></details>`;
    const q=id=>container.querySelector('#'+id),listen=(id,type,f)=>q(id).addEventListener(type,f,{signal:abort.signal});
    const reasons={feedback:'Trusted audit/measurement feedback is missing. Selection is held.','stale-feedback':'The audited source version changed; obtain current feedback before learning.',ambiguous:'More than one program fits. Collect more warranted calibration evidence.','no-candidate':'No available program fits all answers. Check evidence or the supplied language.','calibration-scope':'The complete four-case calibration scope is missing.',validation:'A semantic validation measurement disagrees. Installation is held.','validation-scope':'The complete distinct validation scope is missing.',validated:'One candidate fits all calibration answers and passes the separate finite validation. Installation still requires certificate replay.',unique:'One candidate fits calibration. It has not yet passed semantic validation.'};
    function prepare(){evidence=X.makeEvidence();if(!q('expression-trusted').checked)evidence.cases[0].audit.trusted=false;if(q('expression-stale-feedback').checked)evidence.cases[0].audit.version=1;const data=q('expression-data').value;if(data==='sparse'){evidence.cases=evidence.cases.slice(0,1);evidence.cases[0].observations=evidence.cases[0].observations.slice(0,1);}if(data==='conflict'){const o={...evidence.cases[0].observations[0]};o.y=1-o.y;evidence.cases[0].observations.push(o);}if(q('expression-bad-validation').checked)evidence.validation[0].y=1-evidence.validation[0].y;selection=null;qualification=null;artifact=null;comparison=null;result=null;runtimeError=null;render();}
    function grammar(){return q('expression-grammar').checked?X.GRAMMAR.filter(g=>!(g.op==='ge'&&g.rhs===1)):X.GRAMMAR;}
    function select(){if(!evidence)prepare();selection=X.select(evidence,grammar());qualification=null;artifact=null;comparison=null;render();}
    function validate(){if(!selection)select();if(selection.status==='selected')qualification=X.acquire(evidence,grammar());render();}
    function install(){if(qualification&&qualification.status==='qualified')artifact=X.restore(qualification.artifact);result=null;runtimeError=null;comparison=null;render();}
    function runEpisode(){runtimeError=null;let L=X.OLD,route='inherited';const arm=q('expression-arm').value;try{if(artifact&&arm!=='removed'){let check=artifact;if(q('expression-bad-certificate').checked){check=JSON.parse(JSON.stringify(artifact));check.certificate.sourceVersion++;}L=X.library(check);}if(arm==='active'){if(!artifact)throw new Error('Install a qualified expression before using the expanded comparator.');route='active';}result=X.run({...options,n:7,c:3,route,knownFailure},L);render();}catch(error){result=null;runtimeError=error.message;render();}}
    function census(){if(!artifact)return;comparison=X.comparison(artifact,{budget:options.budget,price:options.price});render();}
    function drawCensus(){for(const [id,key] of [['expression-main-census','main'],['expression-stress-census','stress']])q(id).innerHTML=comparison?comparison.map(r=>{const v=r[key];return `<div class="census-row"><strong>${{inherited:'Retained expression',removed:'Expression removed',restored:'Exact expression restored',active:'Conventional expanded'}[r.arm]}</strong><div class="census-bar" role="img" aria-label="${v.correct} correct, ${v.incorrect} incorrect, ${v.withheld} withheld of ${v.total}"><span class="correct-segment" style="width:${100*v.correct/v.total}%"></span><span class="incorrect-segment" style="width:${100*v.incorrect/v.total}%"></span><span class="hold-segment" style="width:${100*v.withheld/v.total}%"></span></div><small>${v.correct} correct · ${v.incorrect} incorrect · ${v.withheld} withheld<br>${v.queries} queries · ${v.work} runtime work units · ${v.missed} missed watches</small></div>`;}).join(''):'<p class="helper">No frozen census run yet.</p>';}
    function drawProgress(){if(!result){q('expression-progress').innerHTML='<p>No fresh episode run yet.</p>';q('expression-reopen').innerHTML='<p>Install the expression, then compare the fresh episode.</p>';return;}const old=X.run({...options,permission:false},X.OLD),rows=result.history,other=old.history,maxQ=Math.max(rows.length,other.length)-1,maxA=35,sx=i=>40+310*i/Math.max(1,maxQ),sy=a=>175-145*a/maxA;
      q('expression-progress').innerHTML=`<svg class="frontier-svg" viewBox="0 0 390 225" role="img" aria-label="Possible required sets after each query; current route ${rows.map(x=>x.actions).join(', ')}; old route ${other.map(x=>x.actions).join(', ')}"><title>Remaining possible required sets</title>${[1,10,20,35].map(a=>`<line x1="40" x2="350" y1="${sy(a)}" y2="${sy(a)}" stroke="#ccd7e1"/><text x="30" y="${sy(a)+4}" text-anchor="end">${a}</text>`).join('')}<polyline fill="none" stroke="#ac4b13" stroke-width="3" stroke-dasharray="5 4" points="${other.map((x,i)=>sx(i)+','+sy(x.actions)).join(' ')}"/><polyline fill="none" stroke="#2359af" stroke-width="3" points="${rows.map((x,i)=>sx(i)+','+sy(x.actions)).join(' ')}"/>${rows.map((x,i)=>`<circle cx="${sx(i)}" cy="${sy(x.actions)}" r="3" fill="#2359af"/><text x="${sx(i)}" y="197" text-anchor="middle">${i}</text>`).join('')}<text x="40" y="220">Completed queries · vertical: possible required sets</text></svg>`;
      q('expression-progress').innerHTML+='<p class="helper">Old proposal: '+(old.proposal===null?'none':X.setName(old.proposal))+' · '+(old.scoring.proposalMatches===false?'wrong in separate scoring':old.proposal===null?'unresolved':'matches this fixture')+'. Current proposal: '+(result.proposal===null?'none':X.setName(result.proposal))+' · '+(result.scoring.proposalMatches===false?'wrong in separate scoring':result.proposal===null?'unresolved':'matches this fixture')+'.</p>';const o=result.oldLeaf;q('expression-reopen').innerHTML=o?`<div class="comparison-row"><span>Old library</span><div class="bar-track"><div class="bar" style="width:${100*o.oldActions.length/35}%"></div></div><span>${o.oldActions.length}</span></div><div class="comparison-row current"><span>Current library</span><div class="bar-track"><div class="bar" style="width:${100*o.actions.length/35}%"></div></div><span>${o.actions.length}</span></div><p>${o.oldActions.length} → ${o.actions.length} possible required sets on the same ${o.observations.length} inherited answers. A singleton is conditional on coverage; zero support warrants no answer.</p>`:'<p>This episode stopped before the inherited leaf, or uses active diagnosis from the expanded root.</p>';
    }
    function render(){const a=qualification||selection,installed=!!artifact;
      q('expression-guide-count').textContent='GUIDED STAGE '+(stage+1)+' OF 6';q('expression-steps').innerHTML=stages.map((s,i)=>`<button type="button" class="guide-step ${i===stage?'active':''}" aria-current="${i===stage?'step':'false'}" data-stage="${i}">${i+1} · ${s[0]}</button>`).join('');q('expression-guide-title').textContent=stages[stage][1];q('expression-guide-description').textContent=stages[stage][2];q('expression-back').disabled=stage===0;q('expression-next').textContent=stage===5?'Return to the beginning':'Next: '+stages[stage+1][0].toLowerCase();
      q('expression-select').disabled=!evidence;q('expression-validate').disabled=!selection||selection.status!=='selected';q('expression-install').disabled=!qualification||qualification.status!=='qualified';q('expression-compare').disabled=!artifact;q('expression-runtime-audit').disabled=!result;
      q('expression-learning-status').textContent=installed?'Checked expression retained. Receiving permission is '+(options.permission?'supplied separately.':'still off.'):a?((a.candidate?'Candidate '+X.label(a.candidate)+'. ':'')+(reasons[a.reason]||a.reason)):evidence?'Audit evidence collected. Select a candidate next.':'Begin by collecting the supplied audit evidence.';
      q('expression-survivors').textContent=a&&a.ledger.length?String(a.survivors.length):'—';q('expression-calibration').textContent=evidence?String(evidence.cases.reduce((s,x)=>s+x.observations.length,0)):'0';q('expression-mismatches').textContent=qualification&&qualification.validationMismatches!==null?String(qualification.validationMismatches):'—';
      q('expression-library').innerHTML=`<span>AND · s=c</span><span>XOR · s mod 2=1</span>${installed?'<span class="acquired">Acquired · '+esc(X.label(artifact.expression))+'</span>':'<span class="absent">'+(a&&a.candidate?'Candidate '+esc(X.label(a.candidate))+' · not installed':'New expression not installed')+'</span>'}`;
      q('expression-certificate').textContent=installed?'Expression certificate: 88 calibration observations, 3,100 validation measurements, zero mismatches. Exact binding replay passed. Grammar and selector unchanged.':'The runtime library contains only AND/XOR until a candidate passes validation and installation replay.';
      q('expression-explanation').innerHTML=installed?'<strong>A model expression was acquired; no receiving grant was created.</strong><p>It can expose missing alternatives and guide further enquiry. Finite validation remains separate from runtime coverage and current authority.</p>':`<strong>${a?esc(reasons[a.reason]||a.reason):'Identify the failure, then learn from warranted evidence.'}</strong><p>Selection criterion: one survivor. Validation ceiling: zero mismatches. Failed attempts leave the smaller installed library in place.</p>`;
      q('expression-ledger').innerHTML=a&&a.ledger.length?`<div class="table-wrap"><table class="inspector-table expression-ledger"><caption class="helper">${a.grammarCount} candidates · ${a.selectionPredictions} calibration prediction evaluations</caption><thead><tr><th>Program</th><th>Mismatch count / ${a.calibrationCount}</th><th>Result</th></tr></thead><tbody>${a.ledger.map(r=>`<tr class="${r.mismatches?'':'surviving'}"><td>${esc(r.label)}</td><td><div class="mismatch-cell"><span>${r.mismatches}</span><span class="bar-track"><span class="bar" style="width:${100*r.mismatches/a.calibrationCount}%"></span></span></div></td><td>${r.mismatches?'Excluded':'Survives'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="helper">Collect trusted evidence and run selection to see the computed ledger.</p>';
      q('expression-data-description').textContent=evidence?'The selector receives audited K and measured q/y, not an OR label. '+evidence.cases.length+' calibration case(s) collected; validation measurements remain separate. The supplied audits assume a reliable source.':'No calibration feedback collected yet. The default runtime below uses the smaller old library.';
      q('expression-case-table').innerHTML=evidence?`<table class="inspector-table"><thead><tr><th>Scope</th><th>Old proposal</th><th>Audited set</th><th>Answers</th></tr></thead><tbody>${evidence.cases.map(x=>`<tr><td>n=${x.n}, c=${x.c}</td><td>${X.setName(x.audit.proposal,x.n)}</td><td>${X.setName(x.audit.actualK,x.n)}</td><td>${x.observations.length}</td></tr>`).join('')}</tbody></table>`:'';
      const r=result;q('expression-runtime-result').innerHTML=runtimeError?'<strong>Receiving action: HOLD</strong><p>'+esc(runtimeError)+'</p>':r?`<strong>${r.decision==='admit'?'Simulated admission: '+X.setName(r.proposal):'Receiving action: HOLD'}${r.scoring.incorrect?' · wrong in separate simulator scoring':r.scoring.proposalMatches===false?' · wrong model proposal withheld':''}</strong><p>Reason: ${esc({'receiving-permission':'current receiving permission absent',budget:'deadline exhausted',current:'current receipt, permission and duties passed; correctness remains conditional on model coverage',coverage:'this fixture has a known audited coverage contradiction',watch:'continuing watch missed',stale:'source version changed', 'query-permission':'query access absent','refresh-permission':'refresh access absent','empty-support':'no represented model fits'}[r.reason]||r.reason)}. ${r.O.length} queries; ${r.work} runtime work units; decision at tick ${r.decisionTick}/${r.ticks}.</p><p>Proposal: ${r.proposal===null?'none':X.setName(r.proposal)}. Simulator truth is used only for responses and separate scoring.</p>`:'<strong>Run a fresh episode to inspect the diagnostic path.</strong><p>Receiving permission starts off. Installing an expression cannot change it.</p>';
      q('expression-watch-summary').textContent=r?'Watch ticks serviced '+r.serviced+'/'+Math.floor(r.ticks/3)+'; missed '+r.missed+'. Continuing duties traced through the complete '+r.ticks+'-tick window.':'No runtime window traced yet.';
      const symbols={query:'Q',refresh:'R',qualification:'C',admission:'A',watch:'W','missed-watch':'!','idle':'·'};q('expression-ticks').innerHTML=r?r.trace.map(t=>`<div class="runtime-tick ${t.kind}" title="Tick ${t.tick}: ${t.kind}"><strong>${symbols[t.kind]}</strong><small>${t.tick}</small></div>`).join(''):'';
      q('expression-runtime-trace').innerHTML=r?`<div class="table-wrap"><table class="inspector-table"><thead><tr><th>Query / tick</th><th>Question → answer</th><th>Worlds / sets</th></tr></thead><tbody>${r.history.map(h=>`<tr><td>${h.query} / ${h.tick}</td><td>${h.q?X.setName(h.q)+' → '+h.y:'Before observation'}</td><td>${h.worlds} / ${h.actions}</td></tr>`).join('')}</tbody></table></div><p>Logical plan work: ${r.counts.predictions} response predictions; ${r.counts.scores} query scores; ${r.counts.nodes} nodes; ${r.counts.replays} represented-world replays; ${r.counts.replayPredictions} qualification predictions. Identical plans are memoized by the simulator; these counters describe fresh logical construction, not measured elapsed time.</p>`:'';
      q('expression-runtime-audit-result').textContent=auditMessage?auditMessage:knownFailure?'A trusted exact-set audit found a contradiction in this fresh fixture. Subsequent receiving use holds. No additional expression is installed.':'No fresh-runtime audit contradiction recorded. Census scoring is read-only and is never learning feedback.';
      q('expression-comparison-description').textContent=comparison?'Main census: '+options.budget+' ticks, '+options.price+' query price. Frozen before scoring. Counts are this toy’s exact populations, not the paper’s larger corpus.':'Install a checked expression, then run the census. No census outcome is used to revise it.';
      drawProgress();drawCensus();G.annotate(container);
    }
    function go(next){stage=next;if(stage===1&&!evidence)prepare();if(stage===2&&!selection)select();if(stage===3&&!qualification)validate();if(stage===4&&!artifact)install();if(stage===5){runEpisode();if(artifact)census();}render();}
    listen('expression-audits','click',()=>{stage=1;prepare();});listen('expression-select','click',()=>{stage=2;select();});listen('expression-validate','click',()=>{stage=3;validate();});listen('expression-install','click',()=>{stage=4;install();});listen('expression-next','click',()=>go((stage+1)%stages.length));listen('expression-back','click',()=>go(Math.max(0,stage-1)));listen('expression-steps','click',e=>{const b=e.target.closest('[data-stage]');if(b)go(Number(b.dataset.stage));});listen('expression-glossary','click',()=>G.showGlossary());
    for(const id of ['expression-trusted','expression-data','expression-grammar','expression-bad-validation','expression-stale-feedback'])listen(id,'change',()=>{evidence=null;selection=null;qualification=null;artifact=null;result=null;comparison=null;stage=0;render();});
    for(const [id,key] of [['expression-budget','budget'],['expression-price','price'],['expression-mode','mode'],['expression-K','K']])listen(id,'change',()=>{options[key]=['budget','K'].includes(key)?Number(q(id).value):q(id).value;result=null;if(key==='mode'||key==='K'){knownFailure=false;auditMessage=null;}comparison=null;render();});
    for(const [id,key] of [['expression-permission','permission'],['expression-query','queryPermission'],['expression-refresh','refreshPermission'],['expression-watch','watch'],['expression-stale','stale']])listen(id,'change',()=>{options[key]=q(id).checked;result=null;runtimeError=null;render();});
    listen('expression-arm','change',()=>{result=null;runtimeError=null;render();});listen('expression-bad-certificate','change',()=>{result=null;runtimeError=null;render();});listen('expression-run','click',runEpisode);listen('expression-compare','click',census);
    listen('expression-runtime-audit','click',()=>{if(!result)return;if(result.scoring.proposalMatches===false){knownFailure=true;auditMessage='Trusted fixture audit: actual set '+X.setName(result.environment.K)+' differs from proposed set '+X.setName(result.proposal)+'. Contradiction recorded; subsequent use holds. No second expression is acquired.';}else auditMessage='Trusted fixture audit: '+(result.proposal===null?'no unique set was proposed.':'the proposed set matches this fixture’s actual set.')+' This does not establish universal coverage.';render();});
    listen('expression-reset','click',()=>{for(const id of ['expression-trusted','expression-query','expression-refresh','expression-watch'])q(id).checked=true;for(const id of ['expression-grammar','expression-bad-validation','expression-stale-feedback','expression-permission','expression-stale','expression-bad-certificate'])q(id).checked=false;q('expression-data').value='full';q('expression-arm').value='inherited';q('expression-budget').value='48';q('expression-price').value='unit';q('expression-mode').value='OR';q('expression-K').value='11';Object.assign(options,{budget:48,price:'unit',permission:false,queryPermission:true,refreshPermission:true,watch:true,stale:false,mode:'OR',K:11});evidence=null;selection=null;qualification=null;artifact=null;comparison=null;result=null;stage=0;knownFailure=false;auditMessage=null;runEpisode();});
    runEpisode();
    if(document.modelContext&&typeof document.modelContext.registerTool==='function'){
      const empty=input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Use an empty object.');};
      const snapshot=()=>({experiment:'acquired-expression',options:{...options},stage,installedExpression:artifact?artifact.expression:null,learning:qualification?{status:qualification.status,reason:qualification.reason,calibration:qualification.calibrationCount,validation:qualification.validationCount,mismatches:qualification.validationMismatches}:selection?{status:selection.status,survivors:selection.survivors}:null,result,knownFailure});
      for(const tool of [{name:'read_expression_experiment',title:'Read acquired expression experiment',description:'Read local learning status and fresh episode; no evidence or permissions changed.',annotations:{readOnlyHint:true},execute(input){empty(input);return snapshot();}},{name:'run_expression_episode',title:'Run fresh expression episode',description:'Run the selected local fixture using existing library and permissions. Never grants permission or acquires an expression.',annotations:{readOnlyHint:false},execute(input){empty(input);q('expression-run').click();return snapshot();}}])try{Promise.resolve(document.modelContext.registerTool({...tool,inputSchema:{type:'object',properties:{},additionalProperties:false}},{signal:abort.signal})).catch(()=>{});}catch{}
    }
    return {dispose(){abort.abort();},snapshot(){return {options:{...options},stage,installedExpression:artifact?artifact.expression:null,learningStatus:qualification?qualification.status:selection?selection.status:null,result,knownFailure};}};
  }
  window.OrchardLab.register({id:'acquired-expression',title:'04 · Learn What Was Missing',version:'0.4.0',contractVersion:1,mount,run});
})();
